import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long w = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);

        long[] sum = new long[105];
        long[] pw = new long[105];
        boolean[] OK = {false};

        long p = 1;
        int mx = 0;
        for (int i = 0; i < 100; i++) {
            sum[i + 1] = p + sum[i];
            pw[i] = p;
            p *= w;
            if (p > (1L << 40)) {
                mx = i;
                break;
            }
        }

        process(0, m, mx, sum, pw, OK);
        System.out.println(OK[0] ? "YES" : "NO");
    }

    static void process(long cur, long target, int pos, long[] sum, long[] pw, boolean[] OK) {
        if (OK[0]) return;
        if (cur == target) {
            OK[0] = true;
            return;
        }
        long remaining = sum[pos + 1];
        long next = pw[pos];

        if (cur - remaining > target) {
            return;
        } else if (cur + remaining < target) {
            return;
        } else {
            if (cur + sum[pos] < target) {
                process(cur + next, target, pos - 1, sum, pw, OK);
            } else if (cur - sum[pos] > target) {
                process(cur - next, target, pos - 1, sum, pw, OK);
            } else {
                process(cur, target, pos - 1, sum, pw, OK);
            }
        }
    }
}
