#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long w, m;
    cin >> w >> m;

    vector<long long> sum(105, 0);
    vector<long long> pw(105, 0);
    bool OK = false;

    long long p = 1;
    int mx = 0;
    for (int i = 0; i < 100; i++) {
        sum[i + 1] = p + sum[i];
        pw[i] = p;
        p *= w;
        if (p > (1LL << 40)) {
            mx = i;
            break;
        }
    }

    function<void(long long, long long, int)> process = [&](long long cur, long long target, int pos) {
        if (OK) return;
        if (cur == target) {
            OK = true;
            return;
        }
        long long remaining = sum[pos + 1];
        long long next = pw[pos];

        if (cur - remaining > target) {
            return;
        } else if (cur + remaining < target) {
            return;
        } else {
            if (cur + sum[pos] < target) {
                process(cur + next, target, pos - 1);
            } else if (cur - sum[pos] > target) {
                process(cur - next, target, pos - 1);
            } else {
                process(cur, target, pos - 1);
            }
        }
    };

    process(0, m, mx);
    cout << (OK ? "YES" : "NO") << "\n";

    return 0;
}
